function isAnagram(s, t) {
  if (s.length !== t.length) return false;
  const count = new Map(); // char -> how many more times s has it than t
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  for (const ch of t) {
    const c = count.get(ch) ?? 0;
    if (c === 0) return false; // t uses ch more often than s
    count.set(ch, c - 1);
  }
  return true;
}

def is_anagram(s: str, t: str) -> bool:
    if len(s) != len(t):
        return False
    count = {}  # char -> how many more times s has it than t
    for ch in s:
        count[ch] = count.get(ch, 0) + 1
    for ch in t:
        c = count.get(ch, 0)
        if c == 0:
            return False  # t uses ch more often than s
        count[ch] = c - 1
    return True

public boolean isAnagram(String s, String t) {
    if (s.length() != t.length()) return false;
    Map<Character, Integer> count = new HashMap<>(); // char -> surplus in s
    for (char ch : s.toCharArray()) count.merge(ch, 1, Integer::sum);
    for (char ch : t.toCharArray()) {
        int c = count.getOrDefault(ch, 0);
        if (c == 0) return false; // t uses ch more often than s
        count.put(ch, c - 1);
    }
    return true;
}

function groupAnagrams(strs) {
  const groups = new Map(); // sorted letters -> words with those letters
  for (const word of strs) {
    const key = word.split('').sort().join('');
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(word);
  }
  return [...groups.values()];
}

