public List<List<String>> groupAnagrams(String[] strs) {
    Map<String, List<String>> groups = new HashMap<>(); // sorted letters -> words
    for (String word : strs) {
        char[] letters = word.toCharArray();
        Arrays.sort(letters);
        String key = new String(letters);
        groups.computeIfAbsent(key, k -> new ArrayList<>()).add(word);
    }
    return new ArrayList<>(groups.values());
}

function topKFrequent(nums, k) {
  const freq = new Map(); // value -> count
  for (const x of nums) freq.set(x, (freq.get(x) ?? 0) + 1);

  // buckets[c] holds the values that appear exactly c times (1 <= c <= n)
  const buckets = Array.from({ length: nums.length + 1 }, () => []);
  for (const [x, c] of freq) buckets[c].push(x);

  const result = [];
  for (let c = buckets.length - 1; c > 0; c--) {
    for (const x of buckets[c]) {
      result.push(x);
      if (result.length === k) return result;
    }
  }
  return result;
}

def top_k_frequent(nums: list[int], k: int) -> list[int]:
    freq = {}  # value -> count
    for x in nums:
        freq[x] = freq.get(x, 0) + 1

    # buckets[c] holds the values that appear exactly c times (1 <= c <= n)
    buckets = [[] for _ in range(len(nums) + 1)]
    for x, c in freq.items():
        buckets[c].append(x)

    result = []
    for c in range(len(buckets) - 1, 0, -1):
        for x in buckets[c]:
            result.append(x)
            if len(result) == k:
                return result
    return result

public int[] topKFrequent(int[] nums, int k) {
    Map<Integer, Integer> freq = new HashMap<>(); // value -> count
    for (int x : nums) freq.merge(x, 1, Integer::sum);

    // buckets.get(c) holds the values that appear exactly c times
    List<List<Integer>> buckets = new ArrayList<>();
    for (int i = 0; i <= nums.length; i++) buckets.add(new ArrayList<>());
    for (Map.Entry<Integer, Integer> e : freq.entrySet()) buckets.get(e.getValue()).add(e.getKey());

    int[] result = new int[k];
    int filled = 0;
    for (int c = nums.length; c > 0; c--) {
        for (int x : buckets.get(c)) {
            result[filled++] = x;
            if (filled == k) return result;
        }
    }
    return result;
}

function productExceptSelf(nums) {
  const n = nums.length;
  const answer = new Array(n).fill(1);
  let prefix = 1; // product of everything left of i
  for (let i = 0; i < n; i++) {
    answer[i] = prefix;
    prefix *= nums[i];
  }
  let suffix = 1; // product of everything right of i
  for (let i = n - 1; i >= 0; i--) {
    answer[i] *= suffix;
    suffix *= nums[i];
  }
  return answer;
}

