    for (int i = 0; i < n; i++) {
        answer[i] = prefix;
        prefix *= nums[i];
    }
    int suffix = 1; // product of everything right of i
    for (int i = n - 1; i >= 0; i--) {
        answer[i] *= suffix;
        suffix *= nums[i];
    }
    return answer;
}

function longestConsecutive(nums) {
  const set = new Set(nums);
  let best = 0;
  for (const x of set) {
    if (set.has(x - 1)) continue; // x is not the start of a run
    let length = 1;
    while (set.has(x + length)) length++; // extend the run x, x+1, ...
    best = Math.max(best, length);
  }
  return best;
}

def longest_consecutive(nums: list[int]) -> int:
