    for (int x : nums) set.add(x);
    int best = 0;
    for (int x : set) {
        if (set.contains(x - 1)) continue; // x is not the start of a run
        int length = 1;
        while (set.contains(x + length)) length++; // extend the run
        best = Math.max(best, length);
    }
    return best;
}

function subarraySum(nums, k) {
