  let prefix = 0;
  let count = 0;
  for (const x of nums) {
    prefix += x;
    count += seen.get(prefix - k) ?? 0; // subarrays ending here with sum k
    seen.set(prefix, (seen.get(prefix) ?? 0) + 1);
  }
  return count;
}

public int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>(); // prefix sum -> how many times seen
    seen.put(0, 1);
    int prefix = 0, count = 0;
    for (int x : nums) {
        prefix += x;
        count += seen.getOrDefault(prefix - k, 0); // subarrays ending here with sum k
        seen.merge(prefix, 1, Integer::sum);
    }
    return count;
}

