class ChainedHashMap {
  constructor(capacity = 4, maxLoad = 0.75) {
    this.buckets = Array.from({ length: capacity }, () => []);
    this.size = 0;
    this.maxLoad = maxLoad;
  }

  hash(key) {
    let h = 0;
    for (const ch of String(key)) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
    return h; // same key -> same number, every time
  }

  index(key) {
    return this.hash(key) % this.buckets.length;
  }

  set(key, value) {
    const bucket = this.buckets[this.index(key)];
    const entry = bucket.find((e) => e[0] === key);
    if (entry) {
      entry[1] = value; // key already present: overwrite
      return;
    }
    bucket.push([key, value]); // new key: append to the chain
    this.size++;
    if (this.size / this.buckets.length > this.maxLoad) this.resize();
  }

  get(key) {
    const bucket = this.buckets[this.index(key)];
    const entry = bucket.find((e) => e[0] === key);
    return entry ? entry[1] : undefined;
  }

  resize() {
    const old = this.buckets;
    this.buckets = Array.from({ length: old.length * 2 }, () => []);
    for (const bucket of old) {
      for (const [k, v] of bucket) this.buckets[this.index(k)].push([k, v]);
    }
  }
}

function isValidSudoku(board) {
  const rows = Array.from({ length: 9 }, () => new Set());
  const cols = Array.from({ length: 9 }, () => new Set());
  const boxes = Array.from({ length: 9 }, () => new Set());
  for (let r = 0; r < 9; r++) {
    for (let c = 0; c < 9; c++) {
      const d = board[r][c];
      if (d === '.') continue; // empty cell
      const b = Math.floor(r / 3) * 3 + Math.floor(c / 3); // box 0..8
      if (rows[r].has(d) || cols[c].has(d) || boxes[b].has(d)) {
        return false; // d is already in this row, column or box
      }
      rows[r].add(d);
      cols[c].add(d);
      boxes[b].add(d);
    }
  }
  return true;
}

