public boolean isValidSudoku(char[][] board) {
    // rows[r][k] == true: digit k + 1 was already seen in row r (same for cols, boxes)
    boolean[][] rows = new boolean[9][9];
    boolean[][] cols = new boolean[9][9];
    boolean[][] boxes = new boolean[9][9];
    for (int r = 0; r < 9; r++) {
        for (int c = 0; c < 9; c++) {
            char d = board[r][c];
            if (d == '.') continue; // empty cell
            int k = d - '1';               // '1'..'9' -> 0..8
            int b = (r / 3) * 3 + c / 3;   // box 0..8
            if (rows[r][k] || cols[c][k] || boxes[b][k]) {
                return false; // d is already in this row, column or box
            }
            rows[r][k] = cols[c][k] = boxes[b][k] = true;
        }
    }
    return true;
}

function encode(strs) {
  let out = '';
  for (const s of strs) {
    out += s.length + '#' + s; // "4#word": length, separator, raw text
  }
  return out;
}

function decode(encoded) {
  const result = [];
  let i = 0;
  while (i < encoded.length) {
    const j = encoded.indexOf('#', i); // the first '#' after i ends the length
    const length = Number(encoded.slice(i, j));
    result.push(encoded.slice(j + 1, j + 1 + length)); // exactly length chars
    i = j + 1 + length; // jump past the string, even if it contains '#'
  }
  return result;
}

public String encode(List<String> strs) {
    StringBuilder sb = new StringBuilder();
    for (String s : strs) {
        sb.append(s.length()).append('#').append(s); // "4#word"
    }
    return sb.toString();
}

public List<String> decode(String encoded) {
    List<String> result = new ArrayList<>();
    int i = 0;
    while (i < encoded.length()) {
        int j = encoded.indexOf('#', i); // the first '#' after i ends the length
        int length = Integer.parseInt(encoded.substring(i, j));
        result.add(encoded.substring(j + 1, j + 1 + length)); // exactly length chars
        i = j + 1 + length; // jump past the string, even if it contains '#'
    }
    return result;
}

function rotate(matrix) {
  const n = matrix.length;
  // 1. Transpose: swap matrix[r][c] and matrix[c][r] above the diagonal
  for (let r = 0; r < n; r++) {
    for (let c = r + 1; c < n; c++) {
      [matrix[r][c], matrix[c][r]] = [matrix[c][r], matrix[r][c]];
    }
  }
  // 2. Reverse every row (mirror left-right)
  for (const row of matrix) {
    row.reverse();
  }
}

