public void rotate(int[][] matrix) {
    int n = matrix.length;
    // 1. Transpose: swap matrix[r][c] and matrix[c][r] above the diagonal
    for (int r = 0; r < n; r++) {
        for (int c = r + 1; c < n; c++) {
            int tmp = matrix[r][c];
            matrix[r][c] = matrix[c][r];
            matrix[c][r] = tmp;
        }
    }
    // 2. Reverse every row (mirror left-right)
    for (int[] row : matrix) {
        for (int left = 0, right = n - 1; left < right; left++, right--) {
            int tmp = row[left];
            row[left] = row[right];
            row[right] = tmp;
        }
    }
}

function spiralOrder(matrix) {
  const result = [];
  let top = 0, bottom = matrix.length - 1;
  let left = 0, right = matrix[0].length - 1;
  while (top <= bottom && left <= right) {
    for (let c = left; c <= right; c++) result.push(matrix[top][c]); // → top row
    top++;
    for (let r = top; r <= bottom; r++) result.push(matrix[r][right]); // ↓ right column
    right--;
    if (top <= bottom) { // a row is still unread: ← bottom row
      for (let c = right; c >= left; c--) result.push(matrix[bottom][c]);
      bottom--;
    }
    if (left <= right) { // a column is still unread: ↑ left column
      for (let r = bottom; r >= top; r--) result.push(matrix[r][left]);
      left++;
    }
  }
  return result;
}

public List<Integer> spiralOrder(int[][] matrix) {
    List<Integer> result = new ArrayList<>();
    int top = 0, bottom = matrix.length - 1;
    int left = 0, right = matrix[0].length - 1;
    while (top <= bottom && left <= right) {
        for (int c = left; c <= right; c++) result.add(matrix[top][c]); // → top row
        top++;
        for (int r = top; r <= bottom; r++) result.add(matrix[r][right]); // ↓ right column
        right--;
        if (top <= bottom) { // a row is still unread: ← bottom row
            for (int c = right; c >= left; c--) result.add(matrix[bottom][c]);
            bottom--;
        }
        if (left <= right) { // a column is still unread: ↑ left column
            for (int r = bottom; r >= top; r--) result.add(matrix[r][left]);
            left++;
        }
    }
    return result;
}

function setZeroes(matrix) {
  const m = matrix.length, n = matrix[0].length;
  let firstColZero = false; // column 0 gets its own flag (matrix[0][0] marks row 0)
  // Pass 1: record zeros as markers in row 0 and column 0
  for (let r = 0; r < m; r++) {
    if (matrix[r][0] === 0) firstColZero = true;
    for (let c = 1; c < n; c++) {
      if (matrix[r][c] === 0) {
        matrix[r][0] = 0; // row r must become zero
        matrix[0][c] = 0; // column c must become zero
      }
    }
  }
  // Pass 2: clear the inner cells whose row or column is marked
  for (let r = 1; r < m; r++) {
    for (let c = 1; c < n; c++) {
      if (matrix[r][0] === 0 || matrix[0][c] === 0) matrix[r][c] = 0;
    }
  }
  // Pass 3: row 0 and column 0 last, because they held the markers
  if (matrix[0][0] === 0) {
    for (let c = 0; c < n; c++) matrix[0][c] = 0;
  }
  if (firstColZero) {
    for (let r = 0; r < m; r++) matrix[r][0] = 0;
  }
}

